-- Deep-UV chemistry, the cooling loop and the advanced packaging components.
--
-- The 350 nm wafer and die family is generated by scripts/node_recipes.lua; the
-- node ladder from 350 nm onward reuses this chemistry. Chiplets and HBM stacks
-- are packaging components, not compute modules: the node recipes consume them
-- when assembling GPUs and multi-core CPUs.

local M = require("scripts.util")

-- A phase-shift mask is a tighter pattern etched into the previous generation
-- of mask. It is consumed by the VLSI exposure step.
M.recipe({
  name = "phase-shift-mask",
  enabled = false,
  category = "chiptorio-fab",
  energy_required = 12,
  ingredients = {
    M.item("litho-mask", 1),
    M.item("glass", 2),
    M.item("copper-plate", 1),
  },
  results = { M.item("phase-shift-mask", 1) },
})

-- Chemical-mechanical planarisation: abrasive silica in an acidic carrier.
M.recipe({
  name = "cmp-slurry",
  enabled = false,
  category = "chemistry",
  energy_required = 5,
  ingredients = {
    M.item("silica", 4),
    M.fluid("water", 20),
    M.fluid("sulfuric-acid", 10),
  },
  results = { M.fluid("cmp-slurry", 20) },
})

-- The insulator between copper interconnect layers.
M.recipe({
  name = "low-k-dielectric",
  enabled = false,
  category = "chemistry",
  energy_required = 8,
  ingredients = {
    M.item("plastic-bar", 2),
    M.fluid("sulfuric-acid", 10),
  },
  results = { M.item("low-k-dielectric", 2) },
})

-- Absorption chiller: water plus process steam becomes chilled coolant.
M.recipe({
  name = "coolant",
  enabled = false,
  category = "chiptorio-cooling",
  energy_required = 5,
  ingredients = {
    M.fluid("water", 100),
    M.fluid("steam", 100),
  },
  results = { M.fluid("coolant", 100) },
})

-- A packaged heat exchanger for the Datacenter itself.
M.recipe({
  name = "cooling-unit",
  enabled = false,
  category = "chemistry",
  energy_required = 6,
  ingredients = {
    M.item("steel-plate", 4),
    M.item("pipe", 8),
    M.item("copper-plate", 4),
    M.fluid("coolant", 10),
  },
  results = { M.item("cooling-unit", 2) },
})

-- Advanced packaging: two or more dies on one interposer.
M.recipe({
  name = "chiplet",
  enabled = false,
  category = "chiptorio-compute",
  energy_required = 24,
  ingredients = {
    M.item("node-350nm-die", 4),
    M.item("low-k-dielectric", 2),
    M.item("copper-plate", 4),
  },
  results = { M.item("chiplet", 1) },
})

-- Stacked memory: several dies bonded into one HBM stack.
M.recipe({
  name = "hbm-stack",
  enabled = false,
  category = "chiptorio-compute",
  energy_required = 18,
  ingredients = {
    M.item("node-350nm-die", 2),
    M.item("copper-plate", 2),
    M.item("plastic-bar", 1),
  },
  results = { M.item("hbm-stack", 1) },
})
